#!/usr/bin/env node
/**
 * Generates public/_redirects (Cloudflare Pages format) so every old Squarespace
 * URL still lands somewhere sensible after the cutover. Runs before each build.
 */
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const content = path.join(root, 'src/content');
const lines = [
  '# Generated by scripts/build-redirects.mjs — edit that script, not this file.',
  '# Old Squarespace URLs -> new site.',
  '/home / 301',
  '/priorities /2026-platform 301',
  '/primary-election /election-dates 301',
  '/general-election-info /election-dates 301',
  '/registration-dates-cutoffs-1 /election-dates 301',
  '/voter-regulations-updates-3 /election-dates 301',
  '/news-1 /news 301',
  '/calendar-of-events /events 301',
  '/candidates-campaigns /candidates 301',
  '/2024-teton-county-candidates /candidates 301',
  '/new-products /support-us 301',
];

function frontmatter(file) {
  const text = fs.readFileSync(file, 'utf8');
  const m = text.match(/^---\n([\s\S]*?)\n---/);
  const fm = {};
  if (m) for (const line of m[1].split('\n')) { const kv = line.match(/^(\w+):\s*(.*)$/); if (kv) fm[kv[1]] = kv[2].replace(/^"|"$/g, ''); }
  return fm;
}

for (const file of fs.readdirSync(path.join(content, 'pages'))) {
  const fm = frontmatter(path.join(content, 'pages', file));
  const slug = file.replace(/\.md$/, '');
  if (!fm.squarespacePath || ['/home', '/candidates-campaigns', '/elected-officials', '/calendar-of-events', '/2024-teton-county-candidates', '/priorities', '/primary-election', '/general-election-info', '/registration-dates-cutoffs-1', '/voter-regulations-updates-3'].includes(fm.squarespacePath)) continue;
  const target = fm.archived === 'true' ? '/' : `/${slug}`;
  if (fm.squarespacePath !== target) lines.push(`${fm.squarespacePath} ${target} 301`);
}
// Cloudflare caps _redirects at 100 "dynamic" rules and counts these deep links
// against it, so only items from 2024 on get exact redirects. Older ones fall
// back to the /events/* and /news-1/* section rules above.
for (const dir of ['events', 'news']) {
  for (const file of fs.readdirSync(path.join(content, dir))) {
    if (!/^20(2[4-9]|[3-9]\d)-/.test(file)) continue;
    const fm = frontmatter(path.join(content, dir, file));
    if (fm.squarespacePath) lines.push(`${fm.squarespacePath} /${dir}/${file.replace(/\.md$/, '')} 301`);
  }
}
// Wildcards last: Cloudflare takes the first matching rule, so exact rules must come first.
lines.push('/news-1/* /news 301', '/events/* /events 301', '/new-products/* /support-us 301', '/s/* /files/:splat 301');
const out = lines.filter((l, i, a) => a.indexOf(l) === i).join('\n') + '\n';
fs.writeFileSync(path.join(root, 'public/_redirects'), out);
console.log(`wrote public/_redirects (${lines.length} rules)`);
